import React, { useState, useEffect } from 'react'
import { Container, Row, Col, Table, Button, Badge } from 'reactstrap'
import { BASE_URL } from '../../utils/config'

const ManageUsers = () => {
   const [users, setUsers] = useState([])
   const [loading, setLoading] = useState(true)
   const [error, setError] = useState(null)

   useEffect(() => {
      const fetchUsers = async () => {
         try {
            // Lấy token từ localStorage (được lưu khi login thành công)
            const token = localStorage.getItem('token')

            const res = await fetch(`${BASE_URL}/users`, {
               method: 'GET',
               headers: {
                  'Authorization': `Bearer ${token}` // Gửi token lên để qua cổng verifyAdmin
               }
            })

            const result = await res.json()

            if (!res.ok) {
               setError(result.message || "Bạn không có quyền truy cập (Yêu cầu Admin)")
            } else {
               setUsers(result.data || [])
            }
            setLoading(false)
         } catch (err) {
            setError("Lỗi kết nối server")
            setLoading(false)
         }
      }
      fetchUsers()
   }, [])

   const deleteUser = async (id) => {
      if (window.confirm("Xóa người dùng này?")) {
         try {
            const token = localStorage.getItem('token')
            const res = await fetch(`${BASE_URL}/users/${id}`, {
               method: 'DELETE',
               headers: {
                  'Authorization': `Bearer ${token}`
               }
            })
            
            if (res.ok) {
               alert("Đã xóa thành công")
               setUsers(prev => prev.filter(u => u._id !== id))
            } else {
               const result = await res.json()
               alert(result.message)
            }
         } catch (err) {
            alert("Lỗi khi xóa")
         }
      }
   }

   return (
      <section className="mt-5 pt-5">
         <Container>
            <Row>
               <Col lg='12'>
                  <div className="d-flex justify-content-between mb-4">
                     <h3 className="fw-bold">Quản lý hệ thống</h3>
                     <Badge color="danger">Admin Panel</Badge>
                  </div>

                  {loading && <h4 className="text-center">Đang kiểm tra quyền Admin...</h4>}
                  {error && <div className="alert alert-danger text-center">{error}</div>}

                  {!loading && !error && (
                     <Table hover responsive className="bg-white shadow-sm border">
                        <thead>
                           <tr>
                              <th>Username</th>
                              <th>Email</th>
                              <th>Role</th>
                              <th className="text-center">Thao tác</th>
                           </tr>
                        </thead>
                        <tbody>
                           {users.map(user => (
                              <tr key={user._id}>
                                 <td>{user.username}</td>
                                 <td>{user.email}</td>
                                 <td>
                                    <Badge color={user.role === 'admin' ? 'danger' : 'success'}>
                                       {user.role}
                                    </Badge>
                                 </td>
                                 <td className="text-center">
                                    <Button color="danger" size="sm" onClick={() => deleteUser(user._id)}>
                                       <i className="ri-delete-bin-line"></i>
                                    </Button>
                                 </td>
                              </tr>
                           ))}
                        </tbody>
                     </Table>
                  )}
               </Col>
            </Row>
         </Container>
      </section>
   )
}

export default ManageUsers
